package com.brisa.local;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.webkit.WebView;import android.widget.Toast;import java.io.*;import java.lang.ref.WeakReference;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
/** SAF cloud references are not offline files. Copy cloud selections before declaring readiness. */
public final class MobileVideoFiles {
 private static WeakReference<Activity> owner=new WeakReference<>(null),player=new WeakReference<>(null);
 static Object call(String type,String name,Class<?>[] sig,Object...args)throws Exception{return Class.forName("com.brisa.local."+type).getMethod(name,sig).invoke(null,args);}
 static boolean local(Uri uri){String a=uri==null?"":uri.getAuthority();return Arrays.asList("media","com.android.providers.media.documents","com.android.externalstorage.documents","com.android.providers.downloads.documents").contains(a);}
 static JSONObject asset(Context c,String id)throws Exception{return (JSONObject)call("a","m",new Class<?>[]{Context.class,String.class},c,id);}
 static JSONObject grant(Context c,String id)throws Exception{return (JSONObject)call("d0","p",new Class<?>[]{Context.class,String.class},c,id);}
 static String hash(Uri uri)throws Exception{StringBuilder b=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(uri.toString().getBytes(StandardCharsets.UTF_8)))b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}
 static File folder(Context c)throws IOException{File d=new File(c.getFilesDir(),"offline");if(!d.isDirectory()&&!d.mkdirs())throw new IOException("No se puede crear la copia local. Revisa el espacio libre.");return d;}
 static boolean ready(Context c,JSONObject record){if(record==null||record.optBoolean("requiresCopy"))return false;String file=record.optString("privateFile");if(!file.isEmpty())try{File f=new File(folder(c),file);return f.getCanonicalFile().getParentFile().equals(folder(c).getCanonicalFile())&&f.isFile()&&f.length()>0&&(record.optLong("size")<=0||f.length()==record.optLong("size"));}catch(Exception e){return false;}String uri=record.optString("localUri",record.optString("uri"));if(uri.isEmpty()||!local(Uri.parse(uri)))return false;try(android.content.res.AssetFileDescriptor fd=c.getContentResolver().openAssetFileDescriptor(Uri.parse(uri),"r")){return fd!=null&&fd.getLength()!=0;}catch(Exception e){return false;}}
 public static boolean assetReady(Context c,JSONObject record){return ready(c,record);}
 public static String list(Context c,String original){try{JSONArray input=new JSONArray(original),out=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<input.length();i++){JSONObject row=input.getJSONObject(i);String id=row.optString("id");if(!seen.add(id))continue;JSONObject a=asset(c,id),g=grant(c,id),record=a!=null?a:g;if(record!=null){boolean offline=ready(c,record);row.put("offlineReady",offline);if(g!=null&&a==null)row.put("providerImport",true);if(!offline){boolean stream=g==null&&DriveStream.streamable(record);row.put("streamable",stream);row.put("storageLabel",g!=null?"Archivo enlazado · descargar copia para verlo sin conexión":stream?"En Drive · se reproduce por internet":"En Drive · preparar sin conexión");}}out.put(row);}return out.toString();}catch(Exception e){return original;}}
 public static void emit(String name,JSONObject detail){try{call("MainActivity","c",new Class<?>[]{String.class,JSONObject.class},name,detail);}catch(Exception ignored){}}
 static void status(String status,String message,long done,long total){try{emit("brisa-video-import",new JSONObject().put("status",status).put("message",message).put("downloadedBytes",done).put("totalBytes",total));}catch(Exception ignored){}}
 public static void selection(Activity a,ArrayList<Uri> uris){owner=new WeakReference<>(a);a.runOnUiThread(()->{try{if(VideoImportService.busy.get())throw new IOException("Espera a que termine la importación actual.");Intent i=new Intent(a,VideoImportService.class).putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris);a.startForegroundService(i);}catch(Exception e){finish("error",e.getMessage());}});}
 static void finish(String state,String message){Activity a=owner.get();if(a!=null)a.runOnUiThread(()->{try{a.getClass().getField("c").setBoolean(a,false);}catch(Exception ignored){}if(!a.isDestroyed())try{WebView v=(WebView)a.getClass().getField("e").get(a);v.evaluateJavascript("window.BrisaVideosChanged&&window.BrisaVideosChanged()",null);}catch(Exception ignored){}});status(state,message,0,0);}
 static boolean copy(Context c,Uri uri,AtomicBoolean cancelled,CancellationSignal signal,OfflineCopy.Progress progress)throws Exception{
  if(uri==null||!"content".equals(uri.getScheme()))throw new IOException("Selecciona un archivo de vídeo desde el selector.");
  boolean persistent=true;try{c.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){persistent=false;}
  String id=hash(uri);JSONObject existing=asset(c,id);if(existing!=null&&ready(c,existing)){existing.put("hidden",false);call("a","z",new Class<?>[]{Context.class,JSONObject.class},c,existing);return false;}
  if(local(uri)&&persistent)return (Boolean)call("d0","a",new Class<?>[]{Context.class,Uri.class},c,uri);
  String name="Vídeo";long size=0;
  try(Cursor cursor=c.getContentResolver().query(uri,new String[]{"_display_name","_size"},null,null,null,signal)){if(cursor!=null&&cursor.moveToFirst()){if(!cursor.isNull(0))name=cursor.getString(0);if(!cursor.isNull(1))size=cursor.getLong(1);}}
  String mime=c.getContentResolver().getType(uri);if((mime==null||!mime.startsWith("video/"))&&!name.matches("(?i).*\\.(mp4|m4v|webm|mov|mkv|3gp)$"))throw new IOException("El archivo elegido no es un vídeo compatible.");
  String ext=name.replaceFirst("^.*\\.","").toLowerCase(Locale.ROOT);if(!Arrays.asList("mp4","m4v","webm","mov","mkv","3gp").contains(ext))ext="mp4";
  File target=new File(folder(c),"import-"+id+"."+ext);
  JSONObject pending=new JSONObject().put("id",id).put("name",name.substring(0,Math.min(256,name.length()))).put("size",size).put("added",System.currentTimeMillis()).put("uri",uri.toString()).put("requiresCopy",true);
  if(!c.getSharedPreferences("brisa-video-grants",0).edit().putString(id,pending.toString()).commit())throw new IOException("No se pudo guardar la selección.");
  long copied;
  try(android.content.res.AssetFileDescriptor fd=c.getContentResolver().openAssetFileDescriptor(uri,"r",signal)){
   if(fd==null)throw new IOException("Drive no entregó el archivo. Comprueba tu conexión y vuelve a seleccionarlo.");
   long expected=size>0?size:fd.getLength();
   try(InputStream in=fd.createInputStream()){copied=OfflineCopy.copy(in,target,expected,cancelled::get,progress);}
  }
  try{
   JSONObject record=new JSONObject().put("id",id).put("kind","video").put("name",name).put("size",copied).put("added",pending.getLong("added")).put("privateFile",target.getName()).put("sourceUri",uri.toString()).put("storageMode","import").put("localUri",Uri.parse("content://"+c.getPackageName()+".offline/"+Uri.encode(target.getName())).toString()).put("hidden",false);
   call("a","z",new Class<?>[]{Context.class,JSONObject.class},c,record);
   c.getSharedPreferences("brisa-video-grants",0).edit().remove(id).commit();return true;
  }catch(Exception e){target.delete();throw e;}
 }
 public static void play(Activity a,String id){a.runOnUiThread(()->{try{JSONObject g=grant(a,id),record=asset(a,id);if(g!=null&&record==null&&!ready(a,g)){new AlertDialog.Builder(a).setTitle("Este vídeo sigue enlazado a Drive").setMessage("La versión anterior guardó el vínculo, pero no una copia completa. Para verlo sin conexión hay que descargarlo una vez; ocupa espacio en este celular.").setPositiveButton("Descargar copia",(d,w)->{ArrayList<Uri> uris=new ArrayList<>();uris.add(Uri.parse(g.optString("uri")));selection(a,uris);}).setNegativeButton("Cancelar",null).show();return;}Uri uri=DriveStream.video(a,id);if(uri==null){String why=DriveStream.streamable(record)?DriveStream.check(a):"";Toast.makeText(a,why.isEmpty()?"No se pudo abrir el vídeo. Vuelve a elegirlo desde Añadir vídeos.":why,Toast.LENGTH_LONG).show();return;}try{Class<?> service=Class.forName("com.brisa.local.PlaybackService");Object s=service.getField("z").get(null);if(s!=null)s.getClass().getMethod("k").invoke(s);}catch(Exception ignored){}a.startActivity(new Intent(a,Class.forName("com.brisa.local.VideoActivity")).putExtra("videoId",id));}catch(Exception e){Toast.makeText(a,"No se pudo abrir el vídeo. Vuelve a seleccionarlo; si está en Drive, necesitas internet para importar la copia.",Toast.LENGTH_LONG).show();}});}
 public static boolean forgetImported(Context c,String id){try{JSONObject a=asset(c,id);if(a==null||!"import".equals(a.optString("storageMode")))return false;File f=new File(folder(c),a.optString("privateFile"));if(!f.getCanonicalFile().getParentFile().equals(folder(c).getCanonicalFile()))return false;if(f.exists()&&!f.delete())return false;c.getSharedPreferences("brisa-assets-v1",0).edit().remove(a.getString("id")).commit();c.getSharedPreferences("brisa-video-grants",0).edit().remove(a.getString("id")).commit();return true;}catch(Exception e){return false;}}
 public static void attachPlayer(Activity a){player=new WeakReference<>(a);}
 public static void playerError(Throwable error){int code=0;try{code=error.getClass().getField("e").getInt(error);}catch(Exception ignored){}String message=code>=4000&&code<5000?"El vídeo está guardado, pero su códec no es compatible con este celular. Prueba una versión MP4 con vídeo H.264 y audio AAC.":code==2001||code==2002?"No se pudo leer el vídeo desde Drive. Comprueba tu conexión o guárdalo sin conexión desde Google Drive.":"No se pudo leer el vídeo completo. Si lo añadiste desde Drive, vuelve a importarlo con conexión y espera a que termine la copia.";Activity a=player.get();if(a!=null)a.runOnUiThread(()->Toast.makeText(a,message,Toast.LENGTH_LONG).show());try{emit("brisa-video-error",new JSONObject().put("message",message).put("code",code));}catch(Exception ignored){}}
}
